class Solution:
    def maximumLength(self, s: str) -> int:
        n = len(s)
        max_length = -1
        
        # Try all possible lengths from n-2 down to 1
        for length in range(n-2, 0, -1):
            # Count occurrences of each special substring of this length
            count = {}
            
            # Generate all substrings of current length
            for i in range(n - length + 1):
                substring = s[i:i + length]
                
                # Check if substring is special (all characters are the same)
                if len(set(substring)) == 1:
                    if substring not in count:
                        count[substring] = 0
                    count[substring] += 1
                    
                    # If we found a special substring that occurs at least 3 times
                    if count[substring] >= 3:
                        return length
        
        return -1
